  1| #include "Adafruit_Debounce.h"
  2| 
  3| /**
  4|  * @brief Construct a new Adafruit_Debounce::Adafruit_Debounce object.
  5|  * 
  6|  * @param pin The pin number associated with the button.
  7|  * @param polarity The polarity to determine the pressed state (default is LOW).
  8|  */
  9| Adafruit_Debounce::Adafruit_Debounce(int16_t pin, bool polarity) {
 10|     _pin = pin;
 11|     _polarity = polarity;
 12|     _buttonState = !_polarity;
 13|     _lastButtonState = !_polarity;
 14| }
 15| 
 16| /**
 17|  * @brief Initialize the debounce object.
 18|  * 
 19|  * This function sets the pin mode based on the polarity and initializes
 20|  * the button states.
 21|  */
 22| void Adafruit_Debounce::begin() {
 23|     if (_pin >= 0) {
 24|         if (_polarity == LOW) {
 25|             pinMode(_pin, INPUT_PULLUP);
 26|         } else {
 27|             #ifdef INPUT_PULLDOWN
 28|             pinMode(_pin, INPUT_PULLDOWN);
 29|             #else
 30|             pinMode(_pin, INPUT);
 31|             #endif
 32|         }
 33|         
 34|         _buttonState = digitalRead(_pin);
 35|         _lastButtonState = _buttonState;
 36|     }
 37| }
 38| 
 39| /**
 40|  * @brief Initialize the debounce object with a given initial state.
 41|  * 
 42|  * @param initialState The initial state to set the button states.
 43|  */
 44| void Adafruit_Debounce::begin(bool initialState) {
 45|     begin();
 46|     _buttonState = initialState;
 47|     _lastButtonState = initialState;
 48| }
 49| 
 50| /**
 51|  * @brief Read the current state of the button.
 52|  * 
 53|  * @return true If the button state matches the polarity.
 54|  * @return false Otherwise.
 55|  */
 56| bool Adafruit_Debounce::read() {
 57|     if (_pin >= 0) {
 58|         return digitalRead(_pin);
 59|     }
 60|     return _buttonState;
 61| }
 62| 
 63| /**
 64|  * @brief Update the button states.
 65|  * 
 66|  * @param bit The state to set the button if pin is invalid.
 67|  */
 68| void Adafruit_Debounce::update(bool bit) {
 69|     _lastButtonState = _buttonState;
 70|     
 71|     if (_pin >= 0) {
 72|         _buttonState = digitalRead(_pin);
 73|     } else {
 74|         _buttonState = bit;
 75|     }
 76| }
 77| 
 78| /**
 79|  * @brief Check if the button is currently pressed.
 80|  * 
 81|  * @return true If the button is pressed.
 82|  * @return false Otherwise.
 83|  */
 84| bool Adafruit_Debounce::isPressed() {
 85|     return _buttonState == _polarity;
 86| }
 87| 
 88| /**
 89|  * @brief Check if the button is currently released.
 90|  * 
 91|  * @return true If the button is released.
 92|  * @return false Otherwise.
 93|  */
 94| bool Adafruit_Debounce::isReleased() {
 95|     return _buttonState != _polarity;
 96| }
 97| 
 98| /**
 99|  * @brief Check if the button was just pressed.
100|  * 
101|  * @return true If the button was just pressed.
102|  * @return false Otherwise.
103|  */
104| bool Adafruit_Debounce::justPressed() {
105|     return (_buttonState != _lastButtonState) && (_buttonState == _polarity);
106| }
107| 
108| /**
109|  * @brief Check if the button was just released.
110|  * 
111|  * @return true If the button was just released.
112|  * @return false Otherwise.
113|  */
114| bool Adafruit_Debounce::justReleased() {
115|     return (_buttonState != _lastButtonState) && (_buttonState != _polarity);
116| }

